# פרק 7 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=7
TITLE='הפרת חובה חקוקה'
SUM=[' <p>עוולת המסגרת השנייה (לצד הרשלנות), המעוגנת ב<strong>סעיף 63</strong> לפקודה. היא "קולטת" חובות מחיקוקים אחרים ומעניקה בגין הפרתם סעד נזיקי.</p> <h3>7.1 יסודות העוולה — סעיף 63</h3> <p>(1) <strong>חובה מכוח חיקוק</strong> שאינו פקודת הנזיקין; (2) החיקוק נועד <strong>לטובת הניזוק</strong> (לפי פירושו הנכון); (3) המזיק <strong>הפר</strong> את החובה; (4) נגרם <strong>נזק</strong>; (5) הנזק הוא מ<strong>סוג הנזק</strong> שהחיקוק נועד למנוע.</p> <h3>7.2 היסוד השלילי</h3> <p>החיקוק, לפי פירושו הנכון, <strong>לא התכוון לשלול</strong> את הסעד הנזיקי. אם נקבע מנגנון אכיפה ייחודי השולל תביעה אזרחית — העוולה לא תקום.</p> <h3>7.3 יחס לרשלנות</h3> <p>העוולה <strong>עצמאית</strong> מהרשלנות — ניתן לתבוע בשתיהן במקביל. חשובה במיוחד להפרת תקני בטיחות ודיני הגנת העובד.</p> <h3>7.4 נקודות מפתח למבחן</h3> <ul><li>חמישה יסודות (ס׳ 63) + יסוד שלילי (אי-שלילת הסעד).</li><li>החיקוק נועד לטובת הניזוק ולמניעת סוג הנזק שנגרם.</li><li>עצמאית מהרשלנות — אפשר לתבוע בשתיהן.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 63 לפקודת הנזיקין — הפרת חובה חקוקה", '', 'עוולת מסגרת ה"קולטת" חובות מחיקוקים אחרים; חמישה יסודות חיוביים ויסוד שלילי (אי-שלילת הסעד).'), ('ע"א 145/80 ועקנין — סיווג והיחס לרשלנות', '', 'דיון בסיווג החובות החקוקות לעניין העוולה וביחס שבינה לבין עוולת הרשלנות.'), ('קליטת תקני בטיחות', '', 'חשיבות העוולה בהפרת חובות בטיחות בעבודה והגנת העובד — בסיס לתביעת פיצוי נזיקי.'), ('ע״א 145/80 ועקנין נ׳ המועצה המקומית בית שמש', 'אדם נפגע בבריכה עירונית. נטען שהבעלים והמפעילים הפרו תקנות רישוי עסקים, בין היתר בכך שלא הציבו שלט אזהרה כנדרש.', 'ביהמ״ש העליון פירט את חמשת היסודות המצטברים של העוולה לפי ס׳ 63 ואימץ את גישת השופט אטקין, שלפיה חיקוק שנועד להגן על הציבור מגן גם על כל אחד מבני הציבור. ההפרה של תקנות הבטיחות הקימה אחריות בנזיקין.'), ('ע״א 245/81 סולטאן נ׳ סולטאן', 'אישה שבעלה גירש אותה בעל כורחה, בניגוד לאיסור הפלילי, תבעה ממנו פיצויים.', 'נקבע שאין סתירה בין עונש פלילי לבין תרופה אזרחית, ושהשאלה מוכרעת לפי תכלית ההוראה. ההוראה נועדה להגן על הנשים כפרטים, ולכן קמה עילה. מכאן החזקה: חיקוק שנועד לטובת פלוני מקים לו עילה, אלא אם החיקוק התכוון לשלול את התרופה.'), ('ע״א 2034/98 אמין נ׳ אמין', 'שלושה ילדים שאמם נפטרה ננטשו רגשית על ידי אביהם, שסירב לכל קשר איתם, ונגרם להם נזק נפשי קשה ומתמשך.', 'ההזנחה הרגשית החמורה הפרה את חובות ההורה לפי חוק הכשרות המשפטית והאפוטרופסות, שנועדו לטובת הקטין, והקימה אחריות בנזיקין בגין הפרת חובה חקוקה. נקבע שהורה חייב לפעול לטובת ילדו בזהירות שהורה מסור רגיל היה נוקט. הודגש שמדובר במקרה קיצוני.'), ('ע״א 176/53 עטיה נ׳ רוזנבאום', 'עובד נפגע בידו בזמן שניקה מכונה חשמלית. המעביד טען שהתקין גידור בשיטה המקובלת בארץ ובעולם.', 'החובה לגדר היטב חלקים מסוכנים של מכונה לפי פקודת בתי החרושת היא מוחלטת. המעביד אינו יוצא ידי חובתו בכך שהשתמש בשיטה הנהוגה, אם בפועל בטיחות העובד לא הובטחה. הערעור התקבל.'), ('ע״א 335/80 בריגה נ׳ מוסטפא', 'דיון בשאלה אם הפרת תקנת תעבורה שאסרה על טרקטור לנסוע בכביש מהיר מקימה אחריות לנזקי תאונה.', 'התקנה נועדה למנוע עיכובי תנועה, ולא נזקי גוף בתאונה, ולכן הנזק אינו ״מסוגו או מטבעו״ של הנזק שהחיקוק כוון אליו. השופט בך הבהיר שאין הלכה גורפת השוללת תביעה בגין הפרת תקנות התעבורה: תקנה הקובעת נורמת זהירות יכולה לבסס עילה, בניגוד להוראה מנהלית שנועדה לייעל את התנועה.'), ('ע״א 610/02 מפעל הפיס נ׳ לוטונט מועדון חברים בע״מ', 'מפעל הפיס תבע מתחרה שהפעיל מיזם הימורים, בטענה שהפר איסור פלילי על הגרלות והימורים.', 'גם אם הופר איסור פלילי, התובע צריך להראות שהחיקוק נועד להגן על האינטרס שלו. האיסור נועד להגן על הציבור מפני התמכרות להימורים, ולא על מפעל הפיס מפני נזק כלכלי, ולכן התביעה לפי ס׳ 63 נדחתה.'), ('רע״א 9615/05 שמש נ׳ פוקצ׳טה בע״מ', 'אישה בהריון סעדה עם ילדיה במסעדה, ולקוח אחר עישן בניגוד לחוק. המסעדה לא פעלה להפסקת העישון. בית המשפט לתביעות קטנות פסק לה רק את מחיר הארוחה.', 'הפרת חוק הגבלת העישון היא הפרת חובה חקוקה, שכן החוק נועד להגן על בריאות הנמצאים במקומות ציבוריים. ביהמ״ש הדגיש את חשיבות האכיפה האזרחית לנוכח חולשת האכיפה הציבורית, ובשל הקושי להוכיח נזק ספציפי ושיקולי הרתעה — הוסיף פיצוי.')]
QS=[{'q': 'מהו ההבדל העקרוני בין עוולת הרשלנות לבין עוולת הפרת חובה חקוקה?', 'o': ['ברשלנות רף ההתנהגות נקבע על ידי ביהמ״ש, ובהפרת חובה חקוקה — על ידי המחוקק', 'ברשלנות אין צורך בנזק, ובהפרת חובה חקוקה יש', 'הפרת חובה חקוקה חלה רק על רשויות ציבוריות', 'רשלנות היא עוולה פרטיקולרית והפרת חובה חקוקה אינה עוולה כלל'], 'c': 0, 'e': 'נכון. ברשלנות ביהמ״ש קובע בדיעבד מה היה עושה ״האדם הסביר״, ואילו בס׳ 63 הנורמה כבר קבועה בחיקוק.'}, {'q': 'מה מהבאים אינו נמנה עם יסודות העוולה לפי ס׳ 63?', 'o': ['ההפרה גרמה לנזק', 'הנתבע צפה את הנזק בפועל', 'הנזק הוא מסוגו או מטבעו של הנזק שאליו נתכוון החיקוק', 'החיקוק נועד לטובתו או להגנתו של הניזוק'], 'c': 1, 'e': 'נכון. צפייה סובייקטיבית של הנתבע אינה יסוד בס׳ 63; לעיתים החובה אף מוחלטת וללא קשר לאשמה.'}, {'q': 'האם ניתן לבסס תביעה לפי ס׳ 63 על הפרת סעיף בפקודת הנזיקין עצמה?', 'o': ['לא, כי ס׳ 63 מחריג במפורש את ״פקודה זו״', 'לא, כי ס׳ 63 חל רק על תקנות ולא על חוקים', 'כן, כל חיקוק כשר', 'כן, אבל רק לגבי סעיפי ההגנות'], 'c': 0, 'e': 'נכון. ההחרגה מונעת הפיכה של כל עוולה בפקודה גם להפרת חובה חקוקה.'}, {'q': 'מה קובע ס׳ 63(ב) לפקודה?', 'o': ['שחיקוק שנועד לטובת בני אדם בכלל נחשב כמי שנועד גם לטובת כל פרט מהם', 'שהנטל להוכיח את תכלית החיקוק מוטל על הנתבע', 'שחיקוק פלילי אינו מקים עילה', 'שרק חיקוק המגן על קבוצה מסוימת וקטנה מקים עילה'], 'c': 0, 'e': 'נכון. ס׳ 63(ב) מתייחס ל״בני-אדם בכלל או... בני-אדם מסוג או הגדר״ שהתובע נמנה עמם — ובכך מאמץ את גישת אטקין.'}, {'q': 'מה ההלכה שנקבעה בפרשת סולטאן?', 'o': ['שאין סתירה בין סנקציה פלילית לבין תרופה נזיקית, והכול תלוי בתכלית ההוראה', 'שעונש פלילי שולל תמיד תרופה אזרחית', 'שגירוש אישה בעל כורחה אינו עבירה', 'שס׳ 63 אינו חל על דיני המשפחה'], 'c': 0, 'e': 'נכון. בסולטאן נקבע שהשאלה פרשנית, ונוסחה חזקה בעד התרופה, אלא אם החיקוק התכוון לשלול אותה.'}, {'q': 'בעל מסעדה התיר לסועדים לעשן באולם, בניגוד לחוק הגבלת העישון. סועדת בהריון תבעה אותו. מה הדין לפי פסק הדין שמש נ׳ פוקצ׳טה?', 'o': ['קמה עילה של הפרת חובה חקוקה, שכן החוק נועד להגן על בריאות הנמצאים במקום, וייתכן פיצוי גם כשקשה להוכיח נזק ספציפי', 'קמה עילה רק נגד המעשן, לא נגד המסעדה', 'התביעה תידחה, כי החוק הוא פלילי־מנהלי בלבד', 'התביעה תידחה כי לא הוכח נזק רפואי מוחשי'], 'c': 0, 'e': 'נכון. החוק נועד להגן על בריאות הציבור במקומות ציבוריים, וביהמ״ש העליון הדגיש את חשיבות האכיפה האזרחית.'}, {'q': 'מפעל הפיס תבע מיזם הימורים פרטי בטענה שהפר את האיסור הפלילי על הימורים, וגרם לו אובדן הכנסות. מה הדין?', 'o': ['התביעה תידחה, כי האיסור נועד להגן על הציבור מפני התמכרות ולא על מפעל הפיס', 'התביעה תתקבל, כי מפעל הפיס הוא גוף ציבורי', 'התביעה תידחה רק משום שלא הוכח קשר סיבתי', 'התביעה תתקבל, כי הופר איסור פלילי'], 'c': 0, 'e': 'נכון. כך נפסק בפרשת מפעל הפיס נ׳ לוטונט — התכלית אינה הגנה על המונופול מפני תחרות.'}, {'q': 'תקנה חייבה להחזיק בעלי חיים על ספינה במכלאות כדי למנוע הפצת מחלות. המכלאות לא הותקנו, והכבשים נסחפו לים בסערה. מדוע לא תקום אחריות לפי ס׳ 63?', 'o': ['כי תקנות אינן חיקוק', 'כי בעל הכבשים הסתכן מרצון', 'כי הנזק אינו מסוג הנזק שהתקנה נועדה למנוע', 'כי לא הוכח קשר סיבתי עובדתי'], 'c': 2, 'e': 'נכון. זהו מקרה Gorris v. Scott: התקנה כוונה לסיכון של מחלות, לא של טביעה.'}, {'q': 'מה נקבע בפרשת בריגה נ׳ מוסטפא?', 'o': ['שתקנה שאסרה על טרקטור לנסוע בכביש מהיר נועדה למנוע עיכובי תנועה, ולכן אינה מגינה מפני נזקי תאונה', 'שהסתכנות מרצון חלה על עוולת ס׳ 63', 'שאין לתבוע לעולם בגין הפרת תקנות התעבורה', 'שנהג טרקטור אחראי באחריות מוחלטת לכל תאונה'], 'c': 0, 'e': 'נכון. זו דוגמה ישראלית ליסוד ״סוג הנזק״.'}, {'q': 'מעביד טוען שהגידור שהתקין במכונה הוא הנהוג בכל הענף, אף שבפועל לא מנע את פגיעת העובד. לפי פרשת עטיה, מה הדין?', 'o': ['המעביד חייב רק אם הוכח שהתרשל', 'המעביד פטור, כי העובד ידע שהגידור חלקי', 'המעביד חייב, כי חובת הגידור מוחלטת ואינה מתמלאת בשיטה שלא הבטיחה בפועל את בטיחות העובד', 'המעביד פטור, כי פעל לפי הנוהג המקובל'], 'c': 2, 'e': 'נכון. חובה מוחלטת נבחנת לפי התוצאה שהחיקוק דורש, לא לפי סבירות ההתנהגות.'}, {'q': 'איזו הגנה אינה עומדת לנתבע בתביעה על הפרת חובה חקוקה, לפי לשון הפקודה?', 'o': ['הסתכנות מרצון', 'התיישנות', 'אשם תורם', 'מעשה לפי חיקוק'], 'c': 0, 'e': 'נכון. ס׳ 5(ב) קובע שהגנת ההסתכנות מרצון לא תחול על עוולה הנובעת מאי־מילוי חובה חקוקה.'}, {'q': 'מה העיקרון שנקבע בפרשת אמין נ׳ אמין?', 'o': ['רק נזק גוף מזכה בפיצוי בתוך המשפחה', 'ילדים רשאים לתבוע הורים רק לאחר שמלאו להם 18', 'הפרה חמורה של חובות הורה לפי חוק הכשרות המשפטית והאפוטרופסות יכולה להקים אחריות בהפרת חובה חקוקה', 'הורים חסינים מתביעות נזיקין של ילדיהם'], 'c': 2, 'e': 'נכון. נפסק שהזנחה רגשית קיצונית הפרה את חובות ההורה, שנועדו לטובת הקטין, והקימה אחריות.'}, {'q': 'מה מבחן ״לטובתו או להגנתו״ בודק בפועל?', 'o': ['האם התובע היה מודע לקיום החיקוק', 'האם החיקוק כולל סנקציה פלילית', 'האם החיקוק, לפי פירושו התכליתי, נועד להגן על התובע או על קבוצה שהוא נמנה עליה', 'האם הנתבע התכוון להגן על התובע'], 'c': 2, 'e': 'נכון. זו שאלה פרשנית על תכלית החיקוק — מי המוגן.'}, {'q': 'עובדת נפצעה כשמכונה לא מגודרת התפרקה וחלק ממנה עף לעברה — לא במגע עם החלק שהיה אמור להיות מגודר. מה הגישה הנכונה?', 'o': ['יש אחריות אוטומטית בכל נזק במפעל', 'יש לבחון אם הנזק נופל בגדר הסיכון שהגידור נועד למנוע, והפסיקה נוטה לפרש את סוג הנזק ברוחב סביר', 'אין אחריות, כי ס׳ 63 חל רק על נזקי רכוש', 'אין אחריות, כי הנזק לא נגרם ממגע ישיר בחלק הנע'], 'c': 1, 'e': 'נכון. הפסיקה בוחנת את ״סוג״ הנזק ולא את המנגנון המדויק, ולא אחת הכירה באחריות גם כשהנזק נגרם בדרך חריגה.'}, {'q': 'שוכרת דירה נפגעה כשמעקה במרפסת קרס. התברר שהמעקה לא עמד בדרישות תקנות התכנון והבנייה. נגד מי מתאים לבחון עילה לפי ס׳ 63?', 'o': ['נגד אף אחד, כי תקנות בנייה אינן חיקוק', 'רק נגד הרשות המקומית', 'נגד כל אדם שהיה בדירה', 'נגד מי שהחיקוק הטיל עליו את החובה (למשל הקבלן או הבעלים, לפי התקנה)'], 'c': 3, 'e': 'נכון. העוולה מופנית נגד ״מי שאינו מקיים חובה המוטלת עליו״ — יש לזהות את נושא החובה לפי לשון החיקוק.'}, {'q': 'בעל עסק טוען שאי־הצבת שלט אזהרה כנדרש בתקנות לא השפיעה, כי התובע עיוור ולא היה יכול לקרוא אותו. איזה יסוד נבחן כאן?', 'o': ['סוג הנזק', 'קשר סיבתי עובדתי', 'שלילת התרופה', 'תכלית החיקוק'], 'c': 1, 'e': 'נכון. השאלה היא אם אילו הוצב שלט, הנזק היה נמנע — מבחן ״הסיבה שבלעדיה אין״.'}, {'q': 'מה היחס בין חיקוק שקובע אמצעי זהירות לבין שאלת הרשלנות באותו מקרה?', 'o': ['אסור לטעון רשלנות כשיש חיקוק רלוונטי', 'רשלנות וס׳ 63 לא יכולות להיטען באותה תביעה', 'הפרת החיקוק מוכיחה אוטומטית רשלנות, ועמידה בו שוללת אותה', 'החיקוק יכול לשמש אינדיקציה לרף הזהירות, אך עמידה בו אינה שוללת בהכרח רשלנות'], 'c': 3, 'e': 'נכון. החיקוק משפיע על רף הזהירות אך אינו ממצה אותו, ושתי העילות נטענות במצטבר.'}, {'q': 'מה המשמעות של הסיפא בס׳ 63(א) — ״אם החיקוק, לפי פירושו הנכון, התכוון להוציא תרופה זו״?', 'o': ['שכל חיקוק שותק לגבי פיצוי שולל את התרופה', 'שבמקרים שבהם תכלית החיקוק מעידה שלא נועד להקים תרופה נזיקית — אין עילה, אך החזקה היא בעד התרופה', 'שהנתבע יכול לוותר על התרופה', 'שיש להוכיח שהמחוקק התכוון במפורש להעניק פיצוי'], 'c': 1, 'e': 'נכון. זהו היסוד השלילי, וההכרעה בו פרשנית — למשל כשיש הסדר תרופתי ממצה בחיקוק עצמו.'}, {'q': 'רשות מקומית הוסמכה בחוק (״רשאית״) לפקח על מבנים מסוכנים ולא הפעילה את הסמכות. תושב נפגע מקריסת מבנה. מה ההערכה הנכונה?', 'o': ['סמכות שבשיקול דעת היא בסיס חלש לס׳ 63, והתביעה תיבחן בעיקר במסלול הרשלנות', 'הרשות חסינה לחלוטין מכל תביעה', 'התושב יכול לתבוע רק את עובד הרשות באופן אישי', 'קמה אחריות אוטומטית לפי ס׳ 63, כי הופר חיקוק'], 'c': 0, 'e': 'נכון. השאלה אם יש ״חובה״ היא תנאי סף; בהיעדרה, הרשלנות היא המסלול העיקרי (ושם נבחנת חובת הזהירות של רשות ציבורית).'}, {'q': 'עובד הוריד את המגן ממכונה כדי לעבוד מהר יותר, והמעביד ידע ולא עשה דבר. העובד נפגע. מה צפוי?', 'o': ['המעביד אחראי לפי ס׳ 63, וייתכן ניכוי אשם תורם — לרוב בשיעור מתון בתביעות עובדים', 'העובד אינו זכאי לדבר, כי הוא שהפר את התקנה', 'האחריות מתחלקת תמיד חצי־חצי', 'המעביד פטור לגמרי בשל הסתכנות מרצון'], 'c': 0, 'e': 'נכון. אשם תורם חל, אך הפסיקה מתחשבת בכך שחובת הבטיחות נועדה להגן גם מפני חוסר זהירות של העובד.'}, {'q': 'היכן מעוגנת הפרת חובה חקוקה?', 'o': ["ס' 35", "ס' 63", "ס' 23", "ס' 2"], 'c': 1, 'e': 'עוולת מסגרת.'}, {'q': 'החיקוק המקים את העוולה:', 'o': ['חייב להיות פקודת הנזיקין', 'כל חיקוק למעט פקודת הנזיקין', 'רק חוק יסוד', 'רק תקנה'], 'c': 1, 'e': 'קליטת חובות חיצוניות.'}, {'q': 'יסוד מהותי בעוולה:', 'o': ['כוונה לפגוע', 'החיקוק נועד לטובת הניזוק', 'אשם תורם', 'הסכמה'], 'c': 1, 'e': 'תכלית החיקוק.'}, {'q': 'מהו היסוד השלילי?', 'o': ['אין נזק', 'החיקוק לא התכוון לשלול סעד נזיקי', 'אין הפרה', 'אין חובה'], 'c': 1, 'e': 'אם נשלל הסעד — אין עוולה.'}, {'q': 'היחס לרשלנות:', 'o': ['מבטלת אותה', 'עצמאית — ניתן לתבוע במקביל', 'כפופה לה', 'זהה'], 'c': 1, 'e': 'עוולות נפרדות.'}]
